{
  "name": "@rhinohealth/ai-agents",
  "version": "0.1.0",
  "private": true,
  "description": "AI agent platform: LLM gateway, broker, Temporal orchestrator, nova-worker harness, Slack app.",
  "type": "module",
  "workspaces": ["shared", "gateway", "broker", "orchestrator", "harness", "slack-app"],
  "scripts": {
    "build": "npm run build --workspaces --if-present",
    "lint": "eslint .",
    "typecheck": "npm run typecheck --workspaces --if-present",
    "test": "node --import tsx --test \"*/test/**/*.test.ts\"",
    "check": "npm run lint && npm run typecheck && npm test && npm run build"
  },
  "engines": {
    "node": ">=24"
  },
  "devDependencies": {
    "@types/node": "24.12.2",
    "eslint": "10.8.0",
    "tsx": "4.20.3",
    "typescript": "5.9.3",
    "typescript-eslint": "8.65.0"
  }
}

import { z } from "zod";

/** What starts a Nova run (G4-04). The workflow ID is built from key. */
export const Handoff = z.object({
  key: z.string().regex(/^[A-Z]+-\d+$/), // RH-1234
  requester: z.string(), // the Jira accountId of the person who assigned the ticket
  drill: z.boolean().optional(), // drill tickets use minute-scale timers (G3-38)
});
export type Handoff = z.infer<typeof Handoff>;
